function (doc, meta) {
  if (doc.type == "emp" || doc.type == "dept") {
    switch(doc.type) {
      case "dept" :
        emit( [meta.id, 0, doc.name], 0 );
        break;
      case "emp" :
        emit( [doc.dept_id, 1, doc.name ], doc.salary + ((doc.comm)?doc.comm:0) );
        break;
    }
  }
}
